/* ================= navigation ================= */
const RENDER={};let cur='title',booted=false,playBack='train';
const NAVSCREENS=['home','map','region','studio','train','path','quests'];
function go(name,arg){seq.stop();stopGroup();if(typing)typing.finish();$$('.modal-back,.sheet').forEach(m=>m.remove());if(A.busComp)transparentComp(A.busComp);
  $$('.screen').forEach(s=>{s.hidden=s.id!=='s-'+name});const scr=$('#s-'+name);scr.scrollTop=0;scr.classList.remove('enter','puzzle');
  $('#nav').hidden=!NAVSCREENS.includes(name);const navOn={region:'map',quests:'home'}[name]||name;$$('#nav button').forEach(b=>b.classList.toggle('on',b.dataset.go===navOn));
  if(booted){void scr.offsetWidth;scr.classList.add('enter');const w=$('#wipe');w.classList.remove('go');void w.offsetWidth;w.classList.add('go')}booted=true;
  cur=name;RENDER[name](scr,arg);updateBadge();
  if(['home','map','region','train','path','quests'].includes(name))startMusic();else stopMusic()}
function updateBadge(){const b=$('#nav .badge');if(!b||!S)return;const n=dueSkills().length+S.pq.length;b.hidden=!n;b.textContent=n}
function topbar(title,back){return`<div class="topbar">${back?`<button class="iconbtn" data-back="${back}" aria-label="Back">◀</button>`:''}<div class="title">${title}</div><span class="chip amber" title="Coins"><span data-ic="coin" data-sc="2"></span><span class="num" style="font-size:18px">${S.coins}</span></span><span class="chip pink" title="Day streak"><span data-ic="flame" data-sc="2"></span><span class="num" style="font-size:18px">${S.streak}</span></span></div>`}
function wireBack(scr){$$('[data-back]',scr).forEach(b=>b.onclick=()=>{sfx.tap();go(b.dataset.back)})}
function pipSay(html){const d=h('div','pip-say');d.innerHTML=`<span class="pipc"></span><div class="bubble">${html}</div>`;$('.pipc',d).append(pipEl(3,'float'));return d}

/* ================= daily 10-minute session ================= */
const SEGS=[{id:'ear',name:'EAR',min:2,ic:'phones'},{id:'new',name:'NEW',min:3,ic:'scroll'},{id:'practice',name:'PRACTICE',min:3,ic:'drums'},{id:'boss',name:'BOSS',min:2,ic:'skull'}];
const practicable=()=>learnedSkills().filter(id=>SKILL_Q[id]);
function segAvail(id){if(id==='ear')return!!recommendGame();if(id==='new')return true;if(id==='practice')return practicable().length>0;return practicable().length>=2}
function weakestSkill(){const l=practicable();return l.sort((a,b)=>ovr(a)-ovr(b))[0]}
const SEG_DESC={ear:()=>{const g=GAMES.find(x=>x.id===recommendGame());return`Ear training: ${g.name}, 6 quick questions.`},new:()=>{const n=nextStage();return n?`New: ${n.title}. ${n.sub}.`:'New: push a harder Ear Gym tier.'},
  practice:()=>{const d=dueSkills();return d.length?`Practice: recall ${d.map(x=>SK[x].n).join(', ')} before it fades.`:S.pq.length?`Practice: your personal trial, ${PQ[S.pq[0].tag].title}.`:`Practice: sharpen your weakest skill, ${SK[weakestSkill()].n}.`},
  boss:()=>'Boss: today’s remixed monster tests several skills at once.'};
function markSeg(id){if(!id||!SEGS.some(s=>s.id===id))return;if(!S.daily.segs[id]){S.daily.segs[id]=true;save()}}
function finishActivity(cats,dest){[].concat(cats).forEach(markSeg);if(S.daily.active){markSeg(S.daily.active);S.daily.active=null;save();go('home');return}if(Array.isArray(dest))go(dest[0],dest[1]);else go(dest||'home')}
function launchSeg(id){S.daily.active=id;save();
  if(id==='ear')return startGym(recommendGame());
  if(id==='new'){const n=nextStage();return n?openStage(n.id):startGym(recommendGame())}
  if(id==='practice'){if(dueSkills().length)return startRecall();if(S.pq.length)return startPQ(0);return startPractice(weakestSkill())}
  startDailyBoss()}
function renderSession(el){const segs=SEGS.map(s=>Object.assign({},s,{done:!!S.daily.segs[s.id],av:segAvail(s.id)}));const nx=segs.find(s=>!s.done&&s.av);const all=segs.every(s=>s.done);const delta=tierMastery('beg')-S.daily.snap.beg;
  el.innerHTML=`<div class="row sp"><p class="eyebrow" style="color:var(--neon)">TODAY'S 10-MINUTE QUEST</p><span class="today" title="Beginner-tier mastery gained today">${delta>=0?'+':''}${delta.toFixed(1)}%</span></div>
   <div class="segs">${segs.map(s=>`<div class="seg ${s.done?'done':s===nx?'next':!s.av?'lock':''}"><span data-ic="${s.ic}" data-sc="3"${s.done?' data-col="#3ef0c8"':''}></span>${s.name}<b>${s.done?'DONE':s.min+' MIN'}</b></div>`).join('')}</div>
   <p class="muted" style="font-size:14.5px">${all?'Session complete. Come back tomorrow: your recalls will be waiting.':nx?SEG_DESC[nx.id]():'Finish your first lesson to unlock the rest.'}</p>
   ${all?'':`<button class="btn neon block" data-a="seg" ${nx?'':'disabled'}>${Object.keys(S.daily.segs).length?'CONTINUE SESSION ▶':'START TODAY’S SESSION ▶'}</button>`}`;
  hydrateIcons(el);const b=$('[data-a=seg]',el);if(b&&nx)b.onclick=()=>{sfx.tap();launchSeg(nx.id)}}
function sessionSummary(){S.daily.shown=true;save();const delta=tierMastery('beg')-S.daily.snap.beg;const gains=Object.keys(S.skills).map(k=>[k,ovr(k)-(S.daily.snap.sk[k]||0)]).filter(x=>x[1]>0).sort((a,b)=>b[1]-a[1]).slice(0,5);
  reward({eyebrow:'SESSION COMPLETE',title:`TODAY'S MASTERY +${Math.max(0,delta).toFixed(1)}%`,sub:'Beginner-tier mastery gained today. Short and daily is how skills stick.',xp:50,coins:10,lines:gains.map(([k,g])=>`${SK[k].n.toUpperCase()} <b>+${g}%</b>`),btn:'SEE YOU TOMORROW'}).then(()=>RENDER.home($('#s-home')))}

/* ================= title & home ================= */
RENDER.title=scr=>{scr.innerHTML=`<div class="title-scene"></div><div class="title-ui"><div class="logo">BEAT<span>QUEST</span></div><span class="vtag">VERSION ${VERSION}</span><p class="tagline">Learn music production. Earn your tools. Beat the monsters with real skills.</p><div class="title-hero"></div><button class="btn big block" id="start">${S.xp||S.done.length?'CONTINUE':'PRESS START'}</button><p class="eyebrow blink">HEADPHONES RECOMMENDED</p></div>`;
  const cv=lowres(108,200,'bg');$('.title-scene',scr).append(cv);addLive(cv,(g,t,c)=>drawForest(g,t,c,{seed:4}));
  $('.title-hero',scr).append(heroEl(6,'bob'),pipEl(3,'float'));
  $('#start',scr).onclick=()=>{initAudio();sfx.start();haptic(20);go('home')}};
RENDER.home=scr=>{const lp=lvProg();const rk=rankFor(lp.n),rn=rankNext(lp.n);const n=nextStage();const pq=S.pq[0];const learned=learnedSkills().length;
  scr.innerHTML=topbar('BEAT QUEST')+`<div class="stack">
  <div class="win hero-card"><div class="scene"></div><div class="plate"><div class="row sp"><span class="lvl">PRODUCER LV ${lp.n}</span><span class="num muted" style="font-size:20px">${lp.cur} / ${lp.need} XP</span></div><div class="bar"><i style="width:${lp.cur/lp.need*100}%"></i></div>
   <p class="rankline">Now: <b>“${rk[1]}”</b>${rn?`<br>At LV ${rn[0]}: <b>“${rn[1]}”</b>`:''}</p></div></div>
  <div class="memo-slot"></div>
  <div class="win raised stack" style="border-color:#1f5c50" id="session"></div>
  <div class="win raised stack" style="border-color:#6a4718"><p class="eyebrow" style="color:var(--amber)">ADVENTURE</p>
   ${n?`<h2>${n.quest}</h2><p class="muted">${WNAME[n.w]} · ${n.kind.toLowerCase()} · about ${n.mins} min</p>`:`<h2>${S.cert?'Producer certified':'Every world mastered'}</h2><p class="muted">Keep your skills fresh with recalls and the Ear Gym, or open the DAW and produce another track.</p>`}
   <button class="btn big block" id="cont">${n?'CONTINUE ADVENTURE ▶':'OPEN THE FINAL TRACK ▶'}</button></div>
  ${pq?`<div class="win stack" style="border-color:var(--violet)"><p class="eyebrow" style="color:var(--violet)">PERSONAL QUEST</p><h3>${PQ[pq.tag].title}</h3><p class="muted" style="font-size:15px">${PQ[pq.tag].why} Get 3 right to clear it.</p><div class="bar"><i style="width:${pq.prog/pq.goal*100}%;--c:var(--violet)"></i></div><p class="muted" style="font-size:13px">Reward: +120 XP · ${SK[PQ[pq.tag].skill].n} mastery +8%</p><button class="btn violet block" data-a="pq">START TRIAL</button></div>`:''}
  <p class="eyebrow">YOUR PROGRESS</p>
  <div class="statgrid"><div class="stat"><span data-ic="path" data-sc="3"></span><b>${learned}</b><span>skills learned</span></div><div class="stat"><span data-ic="star" data-sc="3"></span><b>${Math.round(tierMastery('beg'))}%</b><span>beginner mastery</span></div><div class="stat"><span data-ic="sword" data-sc="3" data-col="#ff4f9a"></span><b>${S.defeated.length}</b><span>monsters</span></div><div class="stat"><span data-ic="flame" data-sc="3"></span><b>${S.streak}</b><span>day streak</span></div></div>
  <div class="menugrid"><button class="menubtn" data-to="train"><canvas class="px" data-ic="phones"></canvas>EAR GYM</button><button class="menubtn" data-to="studio"><canvas class="px" data-ic="drums"></canvas>MY STUDIO</button><button class="menubtn" data-to="path"><canvas class="px" data-ic="path"></canvas>PRODUCER PATH</button><button class="menubtn" data-to="quests"><canvas class="px" data-ic="scroll"></canvas>DAILY QUESTS</button></div>
  <button class="pip-cta" id="askpip"><span class="pipslot"></span><span class="stack" style="gap:2px"><b>ASK PIP</b><span class="muted" style="font-size:14px">Your producer mentor. Ask anything, like “why does my mix sound quiet?”</span></span></button>
  <div class="row" style="justify-content:center;gap:8px"><button class="btn ghost sm" id="musicT">MUSIC ${S.music?'ON':'OFF'}</button><button class="btn ghost sm" id="settings">SETTINGS</button></div></div>`;
  hydrateIcons(scr);
  const sc=$('.scene',scr);const cv=lowres(108,60,'bg');sc.append(cv);const hw=curWorldId();addLive(cv,hw==='forest'?(g,t,c)=>drawForest(g,t,c,{seed:2}):WSCENE[hw]);
  const hero=heroEl(4,'sprite bob');hero.style.left='calc(50% - 32px)';sc.append(hero);
  const pip=pipEl(3,'sprite float');pip.style.left='calc(50% + 44px)';pip.style.bottom='96px';sc.append(pip);
  const cp=companionEl(3);if(cp){cp.classList.add('sprite');cp.style.left='calc(50% - 80px)';sc.append(cp)}
  $('.memo-slot',scr).replaceWith(pipSay(memoryLine()));
  renderSession($('#session',scr));
  $('.pipslot',scr).append(pipEl(3,'float'));
  $('#cont',scr).onclick=()=>{sfx.tap();continueAdventure()};
  const pqb=$('[data-a=pq]',scr);if(pqb)pqb.onclick=()=>{sfx.tap();startPQ(0)};
  $$('[data-to]',scr).forEach(b=>b.onclick=()=>{sfx.tap();go(b.dataset.to)});
  $('#askpip',scr).onclick=()=>{sfx.tap();openCoach()};
  $('#musicT',scr).onclick=e=>{S.music=!S.music;save();e.currentTarget.textContent='MUSIC '+(S.music?'ON':'OFF');if(S.music)startMusic();else stopMusic()};
  $('#settings',scr).onclick=openSettings;
  if(SEGS.every(s=>S.daily.segs[s.id])&&!S.daily.shown)setTimeout(sessionSummary,400)};
function continueAdventure(){const n=nextStage();if(!n){go('final');return}openStage(n.id)}
let regionW='forest';
function openStage(id){const s=stageById(id);if(!s)return;if(stageState(id)==='locked'){toast(worldOpen(s.w)?'FINISH THE STAGE BEFORE THIS ONE FIRST':'CLEAR THE PREVIOUS WORLD FIRST');return}regionW=s.w;
  if(s.kind==='LESSON')go('lesson',id);else if(s.kind==='CHALLENGE')go('studio',{challenge:true});else if(s.kind==='MASTER TRIAL')go('trial',id);else if(s.kind==='FINAL')go('final');else go('battle',id)}
function openSettings(){const m=modal(`<h2>Settings</h2><p class="muted">Beat Quest ${VERSION}. ${CLOUD.on?'Your progress is saved to your claude.ai account, so it follows you on every device.':'Your progress is saved on this device only.'}</p><button class="btn ghost block st-rs">RESET PROGRESS</button><button class="btn block st-cl">CLOSE</button>`,{dismiss:true});
  let armed=false;$('.st-rs',m).onclick=e=>{const b=e.currentTarget;if(!armed){armed=true;b.textContent='TAP AGAIN TO ERASE EVERYTHING';b.classList.remove('ghost');b.classList.add('pink');return}try{localStorage.removeItem(SAVE_KEY)}catch(err){}S=DEF();S.resetAt=Date.now();S.lastDay=S.firstDay=todayStr();S.quests.day=todayStr();S.daily={day:todayStr(),segs:{},snap:{beg:0,sk:{}},shown:false,active:null};save();stopMusic();m.close();go('title')};$('.st-cl',m).onclick=()=>m.close()}

/* ================= map & region ================= */
RENDER.map=scr=>{scr.innerHTML=topbar('WORLD MAP')+`<p class="muted" style="margin-bottom:10px">Seven worlds, one skill family each. Start at the bottom in Beat Forest and climb toward the Mastering Sky.</p><div class="mapwrap"></div>`;hydrateIcons(scr);
  const w=$('.mapwrap',scr);const cv=lowres(96,238);w.append(cv);drawMap(cv.getContext('2d'));const cw=curWorldId();
  WORLDS.forEach(W=>{const open=worldOpen(W.id),clear=worldDone(W.id);const n=WSTAGES[W.id].filter(x=>S.done.includes(x.id)).length,tot=WSTAGES[W.id].length;
    const b=h('button','mnode '+(clear?'clear':open?'open':'locked'),`<span class="pin">${clear?'<span data-ic="star" data-sc="3" data-col="#3ef0c8"></span>':open?'!':'<span data-ic="lock" data-sc="3"></span>'}</span><span class="lab">${W.name.toUpperCase()}</span>${open&&!clear?`<span class="tag">${n}/${tot} STAGES</span>`:open?'':'<span class="tag">LOCKED</span>'}`);
    b.setAttribute('aria-label',W.name+(clear?' (cleared)':open?'':' (locked)'));b.style.left=W.x/96*100+'%';b.style.top=W.y/238*100+'%';b.onclick=()=>{sfx.tap();if(open)go('region',W.id);else worldInfo(W)};w.append(b)});
  hydrateIcons(w);const f=WORLDS.find(x=>x.id===cw);const hr=heroEl(2,'maphero bob');hr.style.left=(f.x+14)/96*100+'%';hr.style.top=(f.y+6)/238*100+'%';w.append(hr);
  requestAnimationFrame(()=>{const top=hr.offsetTop-scr.clientHeight/2;scr.scrollTop=top>0?top:scr.scrollHeight})};
function worldInfo(W){const skills=SKILLS.filter(s=>s[3]===W.id);const i=WORDER.indexOf(W.id),prev=WORLDS.find(x=>x.id===WORDER[i-1]);
  const m=modal(`<p class="eyebrow">WORLD ${i+1} · LOCKED</p><h2>${W.name}</h2><p>Teaches: ${W.teaches}.</p><p class="muted">${WSTAGES[W.id].length} stages · Boss: ${W.boss}</p>
   <div class="win raised" style="text-align:left;width:100%"><p style="font-size:15px">Clear ${prev?prev.name:'the previous world'} first: finish every stage there, including its Master Trial. Your skills and recalls carry over.</p></div>
   <button class="btn ghost block wi-ok">BACK TO THE MAP</button>`,{dismiss:true});$('.wi-ok',m).onclick=()=>m.close()}
const WCOL={LESSON:'#ffb547',CHALLENGE:'#ffcc4d','MASTER TRIAL':'#a98bff',FINAL:'#ffcc4d'};
RENDER.region=(scr,wid)=>{if(wid)regionW=wid;const w=regionW,W=WORLDS.find(x=>x.id===w),wi=WORDER.indexOf(w);
  scr.innerHTML=topbar(W.name.toUpperCase(),'map')+`<div class="stack"><div class="win region-banner"><div class="scene"></div><div class="over"><p class="eyebrow" style="color:var(--leaf)">WORLD ${wi+1}${wi===0?' · FREE':''}${worldDone(w)?' · CLEARED':''}</p><h2 style="text-shadow:0 2px 0 #000">${W.name}</h2><p style="font-size:15px;text-shadow:0 2px 0 #000">${W.teaches}.</p></div></div><div class="path"></div>${worldDone(w)?`<button class="btn ghost block" data-a="vic">WORLD SUMMARY</button>`:''}</div>`;wireBack(scr);
  const cv=lowres(108,44,'bg');$('.scene',scr).prepend(cv);addLive(cv,WSCENE[w]);
  const p=$('.path',scr);WSTAGES[w].forEach(s=>{const st=stageState(s.id);const col=WCOL[s.kind]||'#ff4f9a';
    const b=h('button','stage '+st,`<span class="ic"><span data-ic="${s.icon}" data-sc="3" data-col="${col}"${st==='locked'?' data-dim="1"':''}></span></span><span class="grow"><span class="k">${s.kind} · ${s.mins} MIN</span><br><span class="t">${s.title}</span><br><span class="s">${s.sub}</span></span><span class="st">${st==='done'?'<span style="color:var(--neon)">CLEAR<br>REPLAY</span>':st==='current'?'<span style="color:var(--amber)">▶ GO</span>':'LOCKED'}</span>`);
    b.onclick=()=>{sfx.tap();openStage(s.id)};p.append(b)});hydrateIcons(scr);const vb=$('[data-a=vic]',scr);if(vb)vb.onclick=()=>go('victory',w)};

/* ================= lessons ================= */
const bt=(p,s,t,v)=>playStep(p,s,t,v);
function waveCanvas(){const cv=lowres(120,30,'viz');const g=cv.getContext('2d');px(g,0,0,120,30,'#08060f');px(g,0,15,120,1,'#1d1736');for(let x=0;x<120;x++){px(g,x,7+Math.round(Math.sin(x/120*Math.PI*4)*5),1,1,'#ffb547');px(g,x,22+Math.round(Math.sin(x/120*Math.PI*24)*5),1,1,'#3ef0c8')}return cv}
const LESSONS={
s0:{title:'What is Sound?',teaches:['sound'],skills:['sound','frequency'],xp:60,coins:10,ability:'ears',game:'freq',
 battle:{mon:'gnat',hp:3,gen:i=>i%2?toneBandQ():highLowQ(1)},
 steps:[
 {k:'DISCOVER',render(b,done){b.innerHTML=`<div class="big-title">Sound is air that vibrates</div>`;b.append(pipSay(`Every sound you hear is air wiggling back and forth. How fast it wiggles is its <b>frequency</b>, measured in <b>Hertz (Hz)</b>: wiggles per second.<br><br>Slow wiggles sound <b>low</b>. Fast wiggles sound <b>high</b>. Your ears catch roughly 20 Hz to 20,000 Hz.`));b.append(waveCanvas(),h('p','muted','Top: a slow, low wave. Bottom: a fast, high one.'));done()}},
 {k:'LISTEN',render(b,done){b.innerHTML=`<div class="big-title">Slow wiggles, fast wiggles</div><p>Play both and watch the wave. The low note draws wide waves. The high note packs them tight.</p><div class="abhost"></div>`;
   abWidget($('.abhost',b),[{label:'110 Hz',note:'A low bass note. 110 wiggles per second.',bpm:120,play:(s,t)=>{if(s%8===0)V.sine(t,110,.6,.32)}},{label:'1,760 Hz',note:'A high whistle. 1,760 wiggles per second.',bpm:120,play:(s,t)=>{if(s%8===0)V.sine(t,1760,.6,.2)}}],done)}},
 {k:'EXPERIMENT',render(b,done,ctx){b.innerHTML=`<div class="big-title">Slide through the spectrum</div><p>Turn the tone on and drag the slider from low to high. Visit all three zones. Low notes need headphones on a phone.</p><div class="bpmread num">440</div><p class="eyebrow" style="text-align:center">HZ</p><button class="btn ghost block" data-a="tone">▶ TURN THE TONE ON</button><input type="range" id="lesson-hz" min="0" max="1000" value="522" aria-label="Frequency"><div class="zone"><span>LOW<br>20–250</span><span>MID<br>250–4k</span><span>HIGH<br>4k–20k</span></div>`;
   const sc=lowres(96,24,'scope');addLive(sc,scopeDraw);b.append(sc);let osc=null,f=440;const seen=new Set();const sl=$('#lesson-hz',b),tb=$('[data-a=tone]',b),zs=$$('.zone span',b);
   const upd=()=>{f=Math.round(40*Math.pow(200,sl.value/1000));$('.bpmread',b).textContent=f;const z=f<250?0:f<4000?1:2;zs.forEach((s,i)=>{s.classList.toggle('on',i===z)});if(osc){osc.frequency.setTargetAtTime(f,now(),.02);seen.add(z);zs[z].classList.add('seen')}if(seen.size===3)done()};
   const off=()=>{if(osc){try{osc.stop()}catch(e){}osc=null}stopGroup();tb.textContent='▶ TURN THE TONE ON'};
   tb.onclick=()=>{if(osc){off();return}initAudio();if(!A.ctx)return;const g=newGroup();osc=A.ctx.createOscillator();osc.type='sine';const vg=A.ctx.createGain();vg.gain.value=.12;osc.connect(vg);vg.connect(g);osc.frequency.value=f;osc.start();tb.textContent='■ TURN THE TONE OFF';upd()};
   sl.oninput=upd;ctx.onLeave(off);upd()}},
 {k:'CHALLENGE',render(b,done){const run=()=>{b.innerHTML=`<div class="big-title">Train your ears</div><p>Four quick tests. Which note is higher? Get <b>3 of 4</b>.</p>`;
   quiz(b,{mode:'lesson',count:4,gen:i=>highLowQ(i<2?1:2),onDone:r=>{const ok=r.ok>=3;const fb=h('p','fb'+(ok?' good':''),ok?`${r.ok}/4. Your ears can already tell high from low.`:`${r.ok}/4. Close! Hum along with each note: your voice knows which is higher.`);b.append(fb);if(ok)done();else{const again=h('button','btn block','TRY AGAIN');again.onclick=run;b.append(again)}}})};run()}}]},
l1:{title:'The Pulse',teaches:['rhythm','bpm','tempo','beats'],skills:['rhythm','bpm','tempo','beats'],xp:60,coins:10,ability:'pulse',game:'tempo',
 battle:{mon:'goblin',hp:3,gen:i=>i%2?tempoQ(1):fasterQ()},
 steps:[
 {k:'DISCOVER',render(b,done){b.innerHTML=`<div class="big-title">Every song has a pulse</div>`;b.append(pipSay(`Tap your foot to any song and you've found its <b>beat</b>. Producers measure how fast beats come in <b>BPM</b>: beats per minute.<br><br>At <b>60 BPM</b> you get one beat every second. At 120 BPM, two.`));
   b.insertAdjacentHTML('beforeend',`<div class="lamp go" style="--dur:1s"></div><p class="muted" style="text-align:center">This lamp is pulsing at 60 BPM.</p><button class="btn ghost block" data-a="hear">▶ HEAR 60 BPM</button>`);
   $('[data-a=hear]',b).onclick=()=>seq.start({bpm:60,total:32,play:(s,t)=>{if(s%4===0)V.click(t,s%16===0)}});done()}},
 {k:'LISTEN',render(b,done){b.innerHTML=`<div class="big-title">Same drums, different speed</div><p>The pattern is identical. Only the tempo changes, and the whole mood changes with it.</p><div class="abhost"></div>`;
   const p=pat({kick:[0,8,10],snare:[4,12],hat:EIGHTHS});abWidget($('.abhost',b),[{label:'80 BPM',note:'Lo-fi hip-hop pace. Laid back.',bpm:80,play:(s,t)=>bt(p,s,t)},{label:'140 BPM',note:'Trap and dubstep pace. Urgent.',bpm:140,play:(s,t)=>bt(p,s,t)}],done)}},
 {k:'EXPERIMENT',render(b,done){const genres=[[60,95,'Hip-hop · Lo-fi'],[96,115,'Pop · R&B'],[116,132,'House · Techno'],[133,160,'Trap · Dubstep'],[161,180,'Drum & bass']];
   b.innerHTML=`<div class="big-title">Drive the tempo</div><p>Drag the slider while the beat plays. Visit three genre zones.</p><div class="bpmread num">100</div><p class="eyebrow" style="text-align:center">BPM</p><input type="range" id="lesson-bpm" min="60" max="180" value="100" aria-label="Tempo in BPM"><div class="ruler">${genres.map(g=>`<div data-lo="${g[0]}" data-hi="${g[1]}"><span>${g[2]}</span><span class="num">${g[0]}–${g[1]}</span></div>`).join('')}</div>`;
   let bpm=100;const seen=new Set();const sl=$('#lesson-bpm',b);const p=pat({kick:[0,8],snare:[4,12],hat:EIGHTHS});
   const mark=()=>{$('.bpmread',b).textContent=bpm;$$('.ruler div',b).forEach(d=>{const on=bpm>=+d.dataset.lo&&bpm<=+d.dataset.hi;d.classList.toggle('on',on);if(on){seen.add(d.dataset.lo);d.classList.add('seen')}});if(seen.size>=3)done()};
   sl.oninput=()=>{bpm=+sl.value;mark()};mark();seq.start({bpm:()=>bpm,play:(s,t)=>bt(p,s,t)})}},
 {k:'CHALLENGE',render(b,done,ctx){b.innerHTML=`<div class="big-title">Lock into the pulse</div><p>Four clicks count you in at 100 BPM. Then tap the pad on every click. Land <b>6 of 8</b> to pass.</p><div class="taph"></div>`;
   tapWidget($('.taph',b),{bpm:100,taps:8,need:6},r=>{ctx.attempt('timing',r.pass);if(r.pass){sfx.ok();done()}else sfx.bad()});
   ctx.hint(b,{hints:['Count “1, 2, 3, 4” out loud with the clicks.','Start moving your finger just before each click, like a drummer’s stick.'],demo:()=>demoTaps(100),demoText:'The high tock marks exactly when to tap.'})}}]},
l2:{title:'Bars & Beats',teaches:['bars','beats'],skills:['bars','beats'],xp:60,coins:10,ability:'grid',
 battle:{mon:'bat',hp:3,gen:i=>[()=>conceptQ('bars'),()=>fourFloorQ(),()=>conceptQ('beats')][i%3]()},
 steps:[
 {k:'DISCOVER',render(b,done){b.innerHTML=`<div class="big-title">Beats come in bars</div>`;b.append(pipSay(`Music counts in groups. Almost all electronic music is in <b>4/4</b>: four beats make one <b>bar</b>. Count along: <b>ONE</b> two three four, <b>ONE</b> two three four.<br><br>A step sequencer slices each beat into 4 steps, so one bar is <b>16 steps</b>.`));
   b.insertAdjacentHTML('beforeend','<div class="gh"></div><button class="btn ghost block" data-a="count">▶ HEAR THE COUNT</button>');
   const g=grid($('.gh',b),{tracks:['kick'],pat:pat({kick:[0,4,8,12]}),edit:false});
   $('[data-a=count]',b).onclick=()=>seq.start({bpm:96,total:32,play:(s,t)=>{if(s%4===0)V.click(t,s%16===0)},onStep:s=>g.step(s%16),onStop:()=>g.step(-1),onEnd:()=>g.step(-1)});done()}},
 {k:'LISTEN',render(b,done){const pA=pat({kick:[0,4,8,12],hat:[2,6,10,14]}),pB=pat({kick:[0,8],hat:[2,6,10,14]});
   b.innerHTML=`<div class="big-title">Where the kick lands</div><p>Watch the grid while each one plays.</p><div class="abhost"></div><div class="gh"></div>`;const g=grid($('.gh',b),{tracks:['kick','hat'],pat:pA,edit:false});
   abWidget($('.abhost',b),[{label:'Four on the floor',note:'Kick on every beat. House and techno.',bpm:122,play:(s,t)=>bt(pA,s,t),onStep:s=>{g.setPat(pA);g.step(s%16)}},{label:'Kick on 1 and 3',note:'Half as busy. Hip-hop and rock feel.',bpm:92,play:(s,t)=>bt(pB,s,t),onStep:s=>{g.setPat(pB);g.step(s%16)}}],done)}},
 {k:'EXPERIMENT',render(b,done){const p=emptyPat();let n=0;b.innerHTML=`<div class="big-title">Place some kicks</div><p>Tap cells to place kicks while the loop plays. The numbered columns are the beats (1, 2, 3, 4). Make at least 3 changes.</p><div class="gh"></div>`;
   const g=grid($('.gh',b),{tracks:['kick'],pat:p,edit:true,onChange:()=>{if(++n>=3)done()}});
   seq.start({bpm:110,play:(s,t)=>{bt(p,s,t);if(s%4===0)V.hat(t,.25)},onStep:s=>g.step(s%16)})}},
 {k:'CHALLENGE',render(b,done,ctx){const p=emptyPat();b.innerHTML=`<div class="big-title">Four on the floor</div><p>Put a kick on <b>every beat</b> of the bar, and nothing in between. Then press CHECK.</p><div class="gh"></div><div class="fbh"></div><button class="btn neon block" data-a="chk">CHECK</button>`;
   const g=grid($('.gh',b),{tracks:['kick'],pat:p,edit:true});seq.start({bpm:120,play:(s,t)=>{bt(p,s,t);if(s%2===0)V.hat(t,.2)},onStep:s=>g.step(s%16)});
   $('[data-a=chk]',b).onclick=()=>{const want=[0,4,8,12];const miss=want.filter(i=>!p.kick[i]).map(i=>i/4+1);const extra=p.kick.map((v,i)=>v&&!want.includes(i)?i+1:0).filter(Boolean);const ok=!miss.length&&!extra.length;ctx.attempt('bars',ok);const fb=$('.fbh',b);
     if(ok){fb.innerHTML='<p class="fb good">Four on the floor. That is the heartbeat of house music.</p>';sfx.ok();done()}else{sfx.bad();fb.innerHTML=`<p class="fb">${miss.length?`Beat ${miss.join(', ')} still has no kick. `:''}${extra.length?`Step ${extra.join(', ')} sits between beats. `:''}Listen: does every count of 1, 2, 3, 4 get a thump?</p>`}};
   ctx.hint(b,{hints:['A bar of 4/4 has four beats. Each one needs a kick.','The beats are the numbered columns: steps 1, 5, 9 and 13.'],demo:()=>{g.mark([0,4,8,12].map(i=>['kick',i]));seq.start({bpm:120,total:32,play:(s,t)=>{if(s%4===0)V.kick(t,.9)},onStep:s=>g.step(s%16),onEnd:()=>{g.step(-1);seq.start({bpm:120,play:(s,t)=>{bt(p,s,t);if(s%2===0)V.hat(t,.2)},onStep:s=>g.step(s%16)})}})},demoText:'The dashed cells are where the kicks go. Listen, then place them yourself.',reveal:()=>{p.kick.forEach((v,i)=>p.kick[i]=i%4===0?1:0);g.paint()}})}}]},
l3:{title:'The Drum Trio',teaches:['kick','snare','hihat','patterns'],skills:['kick','snare','hihat','patterns'],xp:60,coins:10,ability:'drumsense',game:'offbeat',
 battle:{mon:'bug',hp:3,gen:i=>i%2?drumMissingQ():drumSoloQ()},
 steps:[
 {k:'DISCOVER',render(b,done){b.innerHTML=`<div class="big-title">Meet the drum trio</div><p>Most beats are built from three drums. Tap each one to hear it.</p><div class="trio">
   <button data-v="kick"><span data-ic="drums" data-col="#ffb547" data-sc="4"></span><span><b style="color:var(--amber)">KICK</b><p>The low thump. The floor your track stands on.</p></span></button>
   <button data-v="snare"><span data-ic="drums" data-col="#ff4f9a" data-sc="4"></span><span><b style="color:var(--magenta)">SNARE</b><p>The crack. On beats 2 and 4 it becomes the backbeat: the part people clap to.</p></span></button>
   <button data-v="hat"><span data-ic="drums" data-col="#3ef0c8" data-sc="4"></span><span><b style="color:var(--neon)">HI-HAT</b><p>The tick. Quiet, fast hits that fill the space between.</p></span></button></div><p class="muted trio-note">Hear all three to continue.</p>`;hydrateIcons(b);
   const heard=new Set();$$('[data-v]',b).forEach(x=>x.onclick=()=>{initAudio();if(!A.ctx)return;const tk=x.dataset.v;const t=now()+.02;V[tk](t,S.vols[tk]);V[tk](t+.3,S.vols[tk]);haptic(8);heard.add(tk);if(heard.size===3){$('.trio-note',b).textContent='Kick, snare, hat: the whole kit most beats need.';done()}})}},
 {k:'LISTEN',render(b,done){const pA=pat({kick:[0,8],snare:[4,12]}),pB=pat({kick:[0,8],snare:[4,12],hat:EIGHTHS});b.innerHTML=`<div class="big-title">Add the hats</div><p>A has kick and snare only. B adds hi-hats on every 8th note. Hear how B starts moving.</p><div class="abhost"></div><div class="gh"></div>`;
   const g=grid($('.gh',b),{tracks:['kick','snare','hat'],pat:pA,edit:false});abWidget($('.abhost',b),[{label:'Kick + snare',note:'The skeleton.',bpm:96,play:(s,t)=>bt(pA,s,t),onStep:s=>{g.setPat(pA);g.step(s%16)}},{label:'+ hi-hats',note:'The skeleton starts walking.',bpm:96,play:(s,t)=>bt(pB,s,t),onStep:s=>{g.setPat(pB);g.step(s%16)}}],done)}},
 {k:'EXPERIMENT',render(b,done){const p=pat({kick:[0,8]});let n=0;b.innerHTML=`<div class="big-title">Jam with three rows</div><p>Kicks are already down. Add snares and hats anywhere and listen to what changes. Make 3 changes.</p><div class="gh"></div>`;
   const g=grid($('.gh',b),{tracks:['kick','snare','hat'],pat:p,edit:true,onChange:()=>{if(++n>=3)done()}});seq.start({bpm:96,play:(s,t)=>bt(p,s,t),onStep:s=>g.step(s%16)})}},
 {k:'CHALLENGE',render(b,done,ctx){const p=pat({});b.innerHTML=`<div class="big-title">Build a backbeat</div><p>This rhythm is in thousands of songs. Build it, then press CHECK.</p><div class="check"><div data-c="1">Kick on beats 1 and 3</div><div data-c="2">Snare on beats 2 and 4, and nowhere else</div><div data-c="3">Hi-hat on every 8th note (8 per bar)</div></div><div class="gh"></div><div class="fbh"></div><button class="btn neon block" data-a="chk">CHECK</button>`;
   const test=()=>{const a=!!(p.kick[0]&&p.kick[8]&&!p.kick[4]&&!p.kick[12]),s2=p.snare.every((v,i)=>!!v===(i===4||i===12)),c=EIGHTHS.every(i=>p.hat[i]);$('[data-c="1"]',b).classList.toggle('ok',a);$('[data-c="2"]',b).classList.toggle('ok',s2);$('[data-c="3"]',b).classList.toggle('ok',c);return[a,s2,c]};
   const g=grid($('.gh',b),{tracks:['kick','snare','hat'],pat:p,edit:true,onChange:test});seq.start({bpm:96,play:(s,t)=>bt(p,s,t),onStep:s=>g.step(s%16)});
   $('[data-a=chk]',b).onclick=()=>{const r=test();const ok=r.every(Boolean);ctx.attempt('backbeat',r[1]);const fb=$('.fbh',b);if(ok){sfx.ok();fb.innerHTML='<p class="fb good">That is the backbeat. You just programmed the most common drum pattern in pop music.</p>';done()}else{sfx.bad();fb.innerHTML=`<p class="fb">Not yet. Check the list above: the unticked lines still need work. Listen to the loop and count along.</p>`}};
   ctx.hint(b,{hints:['The snare is the part people clap to. Clap along to any pop song: where do your hands land?','Count ONE-two-THREE-four. Kick on ONE and THREE, snare on two and four. Hats on every half-beat.'],demo:()=>{g.mark([['kick',0],['kick',8],['snare',4],['snare',12]].concat(EIGHTHS.map(i=>['hat',i])));const ref=pat({kick:[0,8],snare:[4,12],hat:EIGHTHS});seq.start({bpm:96,total:32,play:(s,t)=>bt(ref,s,t),onStep:s=>g.step(s%16),onEnd:()=>{g.step(-1);seq.start({bpm:96,play:(s,t)=>bt(p,s,t),onStep:s=>g.step(s%16)})}})},demoText:'That is the target groove. The dashed cells show where each hit goes.',reveal:()=>{p.kick.fill(0);p.snare.fill(0);p.hat.fill(0);p.kick[0]=p.kick[8]=1;p.snare[4]=p.snare[12]=1;EIGHTHS.forEach(i=>p.hat[i]=1);g.paint();test()}})}}]},
c1:{title:'Taming Peaks',mission:'comp',teaches:['compression','threshold','ratio','attack','release'],skills:['compression','threshold','ratio','attack','release'],xp:120,coins:20,ability:'dynamic',game:'comp',
 after:async()=>{if(!has('comp')){const r=await unlockTool('comp');if(r==='try'){go('studio');return true}}return false},
 battle:{title:'Peak Beast',custom:(b,done,ctx)=>peakBattle(b,done,ctx)},
 steps:[
 {k:'DISCOVER',render(b,done){b.innerHTML=`<p class="eyebrow" style="color:var(--amber)">COMPRESSION VOLCANO</p><div class="big-title">That thing is hitting way too hard!</div>`;b.append(pipSay(`Listen to the <b>Peak Beast</b>: its slams jump way above everything else. The gap between the quiet parts and the loud parts is called <b>dynamics</b>.<br><br>A <b>compressor</b> turns sound down automatically, but only the part that goes above a line called the <b>threshold</b>. Tame the peaks and the whole groove sits steady.`));
   const arena=h('div','skarena');const cv=lowres(108,40,'bg');arena.append(cv);addLive(cv,drawLava);const ms=h('div','skmon slime');ms.append(monEl('peak',6));arena.append(ms);b.append(arena);seenMon('peak');
   const hb=h('button','btn ghost block','▶ HEAR THE PEAK BEAST');hb.onclick=()=>{initAudio();seq.start({bpm:100,total:32,play:(s,t)=>peakGroove(s,t)})};b.append(hb);done()}},
 {k:'LISTEN',render(b,done){b.innerHTML=`<div class="big-title">Raw versus compressed</div><p>Both versions are matched to the same loudness, so your ears judge the shape, not the volume. After you hear both, compare the waveforms.</p><p class="muted wait">Rendering the beast…</p>`;
   initAudio();if(!A.ctx)return;const spb=60/100/4,dur=32*spb+.6;const sched=t0=>{for(let s=0;s<32;s++)peakGroove(s,t0+s*spb)};
   withTimeout(Promise.all([renderOffline(dur,null,sched),renderOffline(dur,(oc,inp)=>{const k=oc.createDynamicsCompressor();k.threshold.value=-24;k.ratio.value=8;k.knee.value=2;k.attack.value=.003;k.release.value=.12;inp.connect(k);return k},sched)]),6000).then(([raw,cmp])=>{if(!b.isConnected)return;const m=matchLoudness(raw,cmp);$('.wait',b).remove();abBuffers(b,[{label:'Raw beast',note:'Huge slams, quiet body.',buf:m[0]},{label:'Compressed',note:'Slams tamed, body steady.',buf:m[1]}],done)}).catch(()=>{if(!b.isConnected)return;$('.wait',b).textContent='Live version: loudness is not matched on this device, so focus on the shape, not the volume.';abWidget(b,[{label:'Raw beast',note:'Huge slams, quiet body.',bpm:100,play:(s,t)=>peakGroove(s,t)},{label:'Compressed',note:'Slams tamed, body steady.',bpm:100,play:(s,t)=>{const k=liveComp();withRoute(k,()=>peakGroove(s,t))}}],done)})}},
 {k:'EXPERIMENT',render(b,done,ctx){b.innerHTML=`<div class="big-title">Play with the compressor</div><p>Move every control and listen. Discover at least 3 of these:</p><div class="check disc"><div data-d="0">Lower the threshold until the meter moves</div><div data-d="1">Raise the ratio to 4:1 or more while it is working</div><div data-d="2">Try a slow attack (over 30 ms): the snap comes back</div><div data-d="3">Try a long release (over 400 ms): everything ducks and pumps</div></div>`;
   const found=new Set();const rig=compRig(b,{init:{thr:0,ratio:2,att:10,rel:150},onTick:(st,gr)=>{const pk=rig?rig.peakGR():0;const c=[pk>1,st.ratio>=4&&pk>2,st.att>30,st.rel>400];c.forEach((v,i)=>{if(v&&!found.has(i)){found.add(i);$(`[data-d="${i}"]`,b).classList.add('ok');sfx.ok()}});if(found.size>=3)done()}});ctx.onLeave(()=>rig.stop())}},
 {k:'CHALLENGE',render(b,done,ctx){b.innerHTML=`<div class="big-title">Tame the spikes</div><p>Squash the slams to <b>4 dB or less</b> above the threshold, without touching the body of the groove. Use the graph: it shows where each part lands.</p><div class="fbh"></div>`;
   const rig=compRig(b,{init:{thr:0,ratio:1,att:10,rel:120},controls:['thr','ratio']});ctx.onLeave(()=>rig.stop());
   const chk=h('button','btn neon block','CHECK');b.append(chk);chk.onclick=()=>{const m=rig.model();const ok=m.bodyClean&&m.spikeOver<=4&&m.catches;ctx.attempt('dyn',ok);const fb=$('.fbh',b);
     if(ok){sfx.ok();fb.innerHTML=`<p class="fb good">Tamed: the slams now sit ${m.spikeOver.toFixed(1)} dB over the threshold and the body is untouched.</p>`;done()}else{sfx.bad();fb.innerHTML=`<p class="fb">${!m.catches?'The threshold is above the slams, so nothing gets compressed. ':''}${!m.bodyClean?'The threshold is so low that the body gets squashed too. ':''}${m.catches&&m.spikeOver>4?`The slams still jump ${m.spikeOver.toFixed(1)} dB over. `:''}Look at the graph and try again.</p>`}};
   ctx.hint(b,{hints:['On the graph, the threshold is the vertical line. Put it between the body dot and the slam dot.','Then raise the ratio until the slam dot drops close to the threshold level.'],demo:()=>rig.demo(),demoText:'Watch the slam dot drop as the compressor works. Now set it yourself.',reveal:()=>rig.solve()})}}]}};

const STEP_GAIN={DISCOVER:['u',8],LISTEN:['l',7],EXPERIMENT:['p',6],CHALLENGE:['p',14]};
RENDER.lesson=(scr,id)=>{const L=LESSONS[id];let i=0,ok=false,hl=0,leave=[];
  const stg=stageById(id)||{w:'forest'};
  const steps=L.steps.concat([{k:'BATTLE',render:(b,done,ctx)=>{if(L.battle.custom){L.battle.custom(b,done,ctx);return}b.innerHTML=`<div class="big-title">Use it in battle!</div>`;skirmish(b,Object.assign(stg.w==='forest'?{}:{scene:arenaFor(stg.w)},L.battle,{onWin:()=>done()}))}}]);
  const labels=steps.map(s=>s.k).concat(['REWARD']);
  scr.innerHTML=`<div class="lhead"><div class="row"><button class="iconbtn" data-a="leave" aria-label="Leave lesson">✕</button><div class="grow"><p class="eyebrow">${WNAME[stg.w].toUpperCase()} · LESSON</p><h3>${L.title}</h3></div><button class="iconbtn" data-a="pip" aria-label="Ask PIP"></button></div><div class="stepper">${labels.map(s=>`<span>${s}</span>`).join('')}</div></div><div class="lbody"></div><div class="lfoot"><button class="btn big block" data-a="next" disabled>NEXT ▶</button></div>`;
  $('[data-a=pip]',scr).append(pipEl(2));$('[data-a=pip]',scr).onclick=()=>openCoach();
  const body=$('.lbody',scr),nx=$('[data-a=next]',scr);
  const cleanup=()=>{leave.forEach(f=>{try{f()}catch(e){}});leave=[]};
  $('[data-a=leave]',scr).onclick=()=>{sfx.tap();cleanup();S.daily.active=null;save();go('region')};
  const ctx={hint:(host,o)=>hintBar(host,Object.assign({},o,{onLevel:l=>{hl=l}})),attempt:(tag,good)=>{tagResult(tag,good);if(!good)loss(L.skills,'p',1);save()},onLeave:fn=>leave.push(fn)};
  const show=()=>{cleanup();seq.stop();stopGroup();ok=false;hl=0;nx.disabled=true;$$('.stepper span',scr).forEach((s,k)=>{s.className=k<i?'ok':k===i?'on':''});body.innerHTML='';body.classList.remove('enter');void body.offsetWidth;body.classList.add('enter');
    const inner=h('div','lbody');body.append(inner);const mine=i;steps[i].render(inner,()=>{if(i===mine&&inner.isConnected&&!ok){ok=true;nx.disabled=false}},ctx);$$('.pipc',inner).forEach(p=>{if(!p.firstChild)p.append(pipEl(3,'float'))});nx.textContent=i===steps.length-1?'FINISH LESSON ★':'NEXT ▶';scr.scrollTop=0};
  nx.onclick=async()=>{sfx.tap();const st=steps[i];const g=STEP_GAIN[st.k];if(g){const f=st.k==='CHALLENGE'?[1,.75,.5,.25,0][clamp(hl,0,4)]:1;gain(L.skills,g[0],g[1]*f);if(st.k==='CHALLENGE')gain(L.skills,'u',5)}save();
    if(i<steps.length-1){i++;show();return}
    cleanup();seq.stop();nx.disabled=true;$$('.stepper span',scr).forEach(s=>s.className='ok');const first=!S.done.includes(id);
    if(first){S.done.push(id);S.lessons++;learn(L.teaches);addMission(L.mission||'drums')}bump('lesson');logEv('lesson',L.teaches[0]);save();
    await reward({eyebrow:'LESSON COMPLETE',title:L.title.toUpperCase(),xp:first?(stg.xp||L.xp):10,coins:first?L.coins:0,lines:first?[`LEARNED: ${L.teaches.map(k=>SK[k].n.toUpperCase()).join(' · ')}`,'FIRST RECALL: TOMORROW']:['PRACTICE BONUS']});
    if(first&&L.ability)await unlockAbility(L.ability);
    if(first&&L.game){const gm=GAMES.find(x=>x.id===L.game);toast('EAR GYM · '+gm.name.toUpperCase()+' UNLOCKED')}
    if(first&&L.after&&await L.after())return;
    if(first&&L.tool&&!has(L.tool)){const r=await unlockTool(L.tool);if(r==='try'){markSeg('new');S.daily.active=null;save();go('studio');return}}
    finishActivity('new',id==='l3'&&first?['battle','slime']:'region')};
  show()};

/* ================= compressor rig (Compression Volcano) ================= */
function peakGroove(s,t){const i=s%16;if(i===0||i===8)V.kick(t,.22);if(i%2===0)V.hat(t,.14);if(i===6||i===14)V.snare(t,.16);if(i===4||i===12){V.snare(t,1);V.kick(t,.9);noiseHit(t,.09,.9,'bandpass',1200,1.2)}}
let PEAK_FALLBACK={spike:6.5,body:-10};
async function calibratePeak(){const spb=60/100/4;const buf=await renderOffline(16*spb+.5,null,t0=>{for(let s=0;s<16;s++)peakGroove(s,t0+s*spb)});const d=buf.getChannelData(0),sr=buf.sampleRate,t0=.05;
  const win=(a,b)=>{let m=0;for(let i=Math.floor(a*sr);i<Math.min(d.length,Math.floor(b*sr));i++)m=Math.max(m,Math.abs(d[i]));return m};
  const sp=Math.max(win(t0+4*spb,t0+5*spb),win(t0+12*spb,t0+13*spb));let bd=0;[0,2,6,8,10,14].forEach(i=>{bd=Math.max(bd,win(t0+i*spb,t0+(i+1)*spb))});
  return{spike:20*Math.log10(sp||1e-4),body:20*Math.log10(bd||1e-4)}}
function peakBattle(b,done,ctx){const M=MONS.peak;seenMon('peak');let hp=4,round=0,hl=0;
  b.innerHTML=`<div class="row sp"><span class="eyebrow" style="color:var(--magenta)">PEAK BEAST · COMPRESSION</span><span class="skhp"></span></div>`;
  const ar=h('div','skarena');const cv=lowres(108,40,'bg');ar.append(cv);addLive(cv,drawLava);const ms=h('div','skmon slime');ms.append(monEl('peak',6));ar.append(ms);const hs=h('div','skhero');hs.append(heroEl(3,'bob'));ar.append(hs);b.append(ar);
  const say=h('p','qprompt');b.append(say);const rig=compRig(b,{init:{thr:0,ratio:6,att:10,rel:120},controls:['thr']});ctx.onLeave(()=>rig.stop());
  const fbh=h('div');const strike=h('button','btn pink block big','STRIKE');const hbHost=h('div');b.append(fbh,strike,hbHost);
  const drawHp=()=>{const e=$('.skhp',b);e.innerHTML='';for(let i=0;i<4;i++)e.append(h('i',i<hp?'':'gone'))};drawHp();
  const R=[
   {c:['thr'],init:()=>rig.set({thr:0,ratio:6}),say:'The Peak Beast slams! Set the threshold so ONLY the slams trigger the compressor.',skill:'threshold',
    test:m=>m.catches&&m.bodyClean&&rig.model().spikeOver<99,why:m=>!m.catches?'The threshold sits above the slams: nothing gets compressed.':!m.bodyClean?'The threshold is so low the body gets squashed too.':'',win:'The threshold now splits the beast: body below, slams above.',
    hints:['On the graph, the green dot is the body and the pink dot is the slam.','Put the purple threshold line between them.']},
   {c:['ratio'],init:()=>{const m=rig.model();if(!(m.catches&&m.bodyClean))rig.solve();rig.set({ratio:1.5})},say:'Its slams still leap out. Raise the ratio until they sit 3 dB or less over the threshold.',skill:'ratio',
    test:m=>m.spikeOver<=3,why:m=>`The slams still come out ${m.spikeOver.toFixed(1)} dB over. A higher ratio pushes harder.`,win:'Squashed! The slam dot dropped to the threshold line.',
    hints:['Ratio decides how much of the overshoot survives.','At 4:1, 12 dB over comes out 3 dB over. Divide the overshoot by the ratio.']},
   {c:['att'],init:()=>rig.set({att:.5}),say:'The beast turns flat and lifeless: an attack this fast crushes the snap of every hit. Bring the punch back but keep control.',skill:'attack',
    test:()=>rig.st.att>=10&&rig.st.att<=40,why:()=>rig.st.att<10?'Still too fast: the first click of each hit is crushed.':'Too slow: the slams escape before the compressor reacts.',win:'Punch is back! The first snap of each hit gets through, then the compressor clamps.',
    hints:['Attack is how fast the compressor grabs. Watch the bright yellow start of each hit on the right graph.','Somewhere between 10 and 40 ms lets the snap through but still catches the slam.']},
   {c:['rel'],init:()=>rig.set({rel:900}),say:'Now the whole groove pumps: every slam drags the next hits down. Fix the release.',skill:'release',
    test:()=>rig.st.rel>=50&&rig.st.rel<=200,why:()=>rig.st.rel>200?'Too long: the compressor is still pushing down when the next hit arrives (the pink bar on the right graph).':'So short it flutters and distorts on each hit.',win:'Clean! The compressor lets go before the next hit arrives.',
    hints:['Release is how fast it lets go after a hit.','The next hit comes 300 ms later (the vertical line on the right graph). Recover before it: 50 to 200 ms.']}];
  function setRound(){const r=R[round];hl=0;rig.controls(r.c);r.init();say.textContent=r.say;fbh.innerHTML='';hbHost.innerHTML='';strike.disabled=false;ctx.hint(hbHost,{hints:r.hints,onLevel:l=>{hl=l},reveal:()=>{if(round===0||round===1)rig.solve();if(round===2)rig.set({att:20});if(round===3)rig.set({rel:120})}})}
  strike.onclick=()=>{const r=R[round];const m=rig.model();const ok=r.test(m);record(r.skill,'p',ok,hl,'dyn');
    if(ok){hp--;drawHp();sfx.crit();ms.classList.remove('hurt');void ms.offsetWidth;ms.classList.add('hurt');popIn(ar,'CRITICAL HIT!','crit');fbh.innerHTML=`<p class="fb good">${r.win}</p>`;strike.disabled=true;
      setTimeout(()=>{if(!b.isConnected)return;round++;if(round>=R.length){ms.classList.add('dead');if(!S.defeated.includes('peak'))S.defeated.push('peak');save();sfx.victory();say.textContent='The Peak Beast is tamed. You just learned threshold, ratio, attack and release by using them.';strike.hidden=true;hbHost.innerHTML='';rig.controls(['thr','ratio','att','rel']);done()}else setRound()},1400)}
    else{sfx.hurt();ar.classList.remove('shake');void ar.offsetWidth;ar.classList.add('shake');popIn(ar,'MISS','miss');fbh.innerHTML=`<p class="fb">${r.why(m)}</p>`}};
  setRound()}

