function scoreBeat(p,v){const n=k=>p[k].filter(Boolean).length;const used=['kick','snare','hat','bass'].filter(k=>n(k)>0);const tips=[];
  let rhythm=40;if(p.kick[0])rhythm+=20;else tips.push('Try a kick on step 1. It tells the listener where the bar starts.');if(p.snare[4]||p.snare[12])rhythm+=20;else tips.push('A snare on beat 2 or 4 (step 5 or 13) gives people something to nod to.');if(n('hat')>=4)rhythm+=20;else tips.push('A few more hi-hats would keep time between the big hits.');
  let structure=0;if(used.some(k=>p[k][0]))structure+=34;const halves=['kick','bass'].some(k=>p[k].slice(0,8).some(Boolean)&&p[k].slice(8).some(Boolean));if(halves)structure+=33;else tips.push('Spread the low end across both halves of the bar so it doesn’t feel lopsided.');const tot=used.reduce((a,k)=>a+n(k),0);if(tot>=10&&tot<=40)structure+=33;else tips.push(tot<10?'The groove is very sparse. That can work, but try a few more hits.':'Lots of hits. Leaving some gaps lets the groove breathe.');
  let balance=100;if(v.hat>v.kick){balance-=25;tips.push('Your hi-hats are louder than your kick. Hats usually sit quieter.')}if(used.some(k=>v[k]<.15)){balance-=20;tips.push('One track is almost silent. Bring it up or remove it.')}if(used.length&&used.every(k=>v[k]>=.95)){balance-=20;tips.push('Every fader is maxed out. Pulling some down makes room for the rest.')}balance=Math.max(40,balance);
  let creativity=40;const notes=new Set(p.bass.filter(Boolean));if(notes.size>=2)creativity+=20;else tips.push('Tap a bass cell again to change its note. Two or three different notes make a bassline.');if(used.some(k=>p[k].some((x,i)=>x&&i%2===1)))creativity+=20;else tips.push('Hits on the in-between steps (2, 4, 6…) add syncopation, that bouncy feeling.');const bb=pat({kick:[0,8],snare:[4,12],hat:EIGHTHS});if(['kick','snare','hat'].some(k=>p[k].some((x,i)=>!!x!==!!bb[k][i])))creativity+=20;
  const completion=used.length*25;const overall=Math.round((rhythm+structure+balance+creativity+completion)/5);return{rhythm,structure,balance,creativity,completion,overall,tips:tips.slice(0,3),used}}
