/* ================= Ear Gym & activities ================= */
RENDER.play=(scr,cfg)=>{playBack=cfg.back||'train';scr.innerHTML=`<div class="lhead"><div class="row"><button class="iconbtn" data-a="leave" aria-label="Leave">✕</button><div class="grow"><p class="eyebrow">${cfg.eyebrow}</p><h3>${cfg.title}</h3></div></div></div><div class="stack pbody"></div>`;
  $('[data-a=leave]',scr).onclick=()=>{sfx.tap();S.daily.active=null;save();go(playBack)};cfg.run($('.pbody',scr))};
function startGym(id,preview){const G=GAMES.find(g=>g.id===id);if(!G)return;const e=S.ear[id]||(S.ear[id]={tier:1,best:0,plays:0});const tier=e.tier;
  go('play',{eyebrow:`EAR GYM${preview&&!G.unlocked()?' · PREVIEW':''} · TIER ${tier}: ${G.tiers[tier-1].toUpperCase()}`,title:G.name,back:preview&&!G.unlocked()?'map':'train',run:body=>{body.append(pipSay(G.intro));
    quiz(body,{mode:'gym',count:6,gen:()=>G.gen(tier),onDone:res=>{e.plays++;const score=res.ok;let up=false;if(score>=5&&e.tier<3){e.tier++;up=true}e.best=Math.max(e.best,score);bump('ear');save();
      reward({eyebrow:'EAR GYM · '+G.name.toUpperCase(),title:`${score}/6 CORRECT`,sub:up?`Tier up! Next round: ${G.tiers[e.tier-1]}.`:score>=5?'Top accuracy. Keep it sharp.':'Get 5 of 6 to reach the next tier.',xp:score*4+res.maxCombo*2,coins:score,lines:[`LISTENING · ${SK[G.skill].n.toUpperCase()} ${Math.round(sk(G.skill).l)}%`]}).then(()=>finishActivity('ear',playBack))}})}})}
function startRecall(){const due=dueSkills().slice(0,3);if(!due.length){toast('NOTHING TO RECALL TODAY');return}
  const plan=[];due.forEach(id=>{const gens=shuffle(SKILL_Q[id]);plan.push([id,gens[0]],[id,gens[1%gens.length]])});const per={};due.forEach(id=>per[id]=[]);
  go('play',{eyebrow:'RECALL · SPACED REPETITION',title:'Recall: '+due.map(id=>SK[id].n).join(', '),back:'train',run:body=>{body.append(pipSay('Quick check before these skills fade. Each right answer pushes the skill further out in time: 1, 3, 7, 14, then 30 days.'));
    quiz(body,{mode:'recall',count:plan.length,gen:i=>{const q=plan[i][1]();q._sk=plan[i][0];return q},onAnswer:(ok,q)=>per[q._sk].push(ok),onDone:()=>{
      const lines=due.map(id=>{const good=per[id].every(Boolean);recallResult(id,good);if(good)gain(id,'u',4);const s=S.skills[id];return`${SK[id].n.toUpperCase()} ${memoHtml(s.box)} ${good?'NEXT IN '+BOX_DAYS[s.box-1]+' DAYS':'AGAIN TOMORROW'}`});
      logEv('recall',due[0]);save();reward({eyebrow:'RECALL COMPLETE',title:'MEMORY UPDATED',xp:10*due.length,coins:2*due.length,lines}).then(()=>finishActivity('practice','train'))}})}})}
function memoHtml(box){let s='<span class="memo">';for(let i=1;i<=5;i++)s+=`<i class="${i<=box?'on':''}"></i>`;return s+'</span>'}
function startPQ(idx){const pq=S.pq[idx||0];if(!pq)return;const T=PQ[pq.tag];
  go('play',{eyebrow:'PERSONAL QUEST',title:T.title,back:'home',run:body=>{body.append(pipSay(`${T.why} Let’s train exactly that. Get 3 right.`));
    quiz(body,{mode:'pq',need:Math.max(1,pq.goal-pq.prog),maxQ:10,gen:()=>T.gen(),onAnswer:ok=>{if(ok){pq.prog++;save()}},onDone:()=>{
      if(pq.prog>=pq.goal){S.pq=S.pq.filter(x=>x!==pq);const s=sk(T.skill);s[T.dim]=clamp(s[T.dim]+8,0,100);if(S.tags[pq.tag])S.tags[pq.tag].r=[];logEv('pqdone',T.skill,pq.tag);save();
        reward({eyebrow:'PERSONAL QUEST COMPLETE',title:T.title.toUpperCase(),xp:120,coins:15,lines:[`${SK[T.skill].n.toUpperCase()} MASTERY +8%`,'WEAKNESS CLEARED']}).then(()=>finishActivity('practice','home'))}
      else{toast(`KEEP GOING · ${pq.prog}/${pq.goal}`);finishActivity('practice','home')}}})}})}
function startPractice(id){const gens=SKILL_Q[id];if(!gens){toast('NO PRACTICE FOR THIS SKILL YET');return}
  go('play',{eyebrow:'PRACTICE · '+SK[id].n.toUpperCase(),title:'Sharpen '+SK[id].n,back:'path',run:body=>quiz(body,{mode:'practice',count:3,gen:()=>pick(gens)(),onDone:res=>reward({eyebrow:'PRACTICE',title:`${res.ok}/3 · ${SK[id].n.toUpperCase()}`,xp:res.ok*5,lines:[`${SK[id].n.toUpperCase()} MASTERY ${ovr(id)}%`]}).then(()=>finishActivity('practice','path'))})})}
function startDailyBoss(){const pool=practicable();if(pool.length<2){toast('LEARN TWO SKILLS TO FACE A DAILY BOSS');return}const mp=S.defeated.filter(m=>MONS[m]&&MONS[m].spr&&m!=='peak');const mon=mp.length?mp[new Date().getDate()%mp.length]:'goblin';
  go('play',{eyebrow:'DAILY BOSS · MULTI-SKILL',title:MONS[mon].name+' (remix)',back:'home',run:body=>skirmish(body,{mon,hp:5,title:MONS[mon].name.toUpperCase()+' · REMIX',intro:`A remixed ${MONS[mon].name} tests everything you have learned so far.`,gen:()=>pick(SKILL_Q[pick(pool)])(),
    onWin:won=>{const b=h('button','btn block big','CLAIM REWARD');body.append(b);b.onclick=()=>reward({eyebrow:'DAILY BOSS',title:won?'REMIX DEFEATED':'IT GOT AWAY',xp:won?60:20,coins:won?15:5}).then(()=>{if(won)bump('defeat');finishActivity('boss','home')})}})})}
RENDER.train=scr=>{const due=dueSkills();const nr=nextRecall();
  scr.innerHTML=topbar('EAR GYM')+`<div class="stack"><p class="muted">Short, replayable listening games. Each round is 6 questions, about 2 minutes. Accuracy raises your <b style="color:var(--ink)">Listening</b> mastery, and 5 of 6 unlocks the next tier.</p>
   <div class="win raised stack" style="border-color:${due.length?'var(--neon)':'var(--edge)'}"><p class="eyebrow" style="color:var(--neon)">RECALL · SPACED REPETITION</p>${due.length?`<h3>${due.length} skill${due.length>1?'s':''} ready: ${due.slice(0,3).map(id=>SK[id].n).join(', ')}</h3><p class="muted" style="font-size:14.5px">Recall right before you forget and the memory lasts longer each time.</p><button class="btn neon block" data-a="recall">START RECALL</button>`:`<p style="font-size:15px">${nr?`Nothing due today. Next recall: ${SK[nr.id].n} in ${nr.days} day${nr.days===1?'':'s'}.`:'Finish a lesson and its skills come back here to be recalled: after 1, 3, 7, 14 and 30 days.'}</p>`}</div>
   ${S.pq.map((q,i)=>`<div class="win stack" style="border-color:var(--violet)"><p class="eyebrow" style="color:var(--violet)">PERSONAL QUEST · ${q.prog}/${q.goal}</p><h3>${PQ[q.tag].title}</h3><p class="muted" style="font-size:14.5px">${PQ[q.tag].why}</p><button class="btn violet block" data-pq="${i}">START TRIAL</button></div>`).join('')}
   <p class="eyebrow">GAMES</p><div class="stack games"></div></div>`;
  hydrateIcons(scr);const gl=$('.games',scr);
  GAMES.forEach(G=>{const open=G.unlocked();const e=S.ear[G.id]||{tier:1,best:0};const b=h('button','gcard'+(open?'':' lock'));b.append(open?icon(G.ic,G.col,4):sprite(ICONS[G.ic],DIM_PAL,4));
    b.insertAdjacentHTML('beforeend',`<span class="stack" style="gap:3px"><span class="t">${open?G.name:'???'}</span><span class="s">${open?`Trains ${SK[G.skill].n} · Tier ${e.tier}: ${G.tiers[e.tier-1]}`:G.how}</span></span><span class="stack" style="gap:2px;align-items:flex-end">${open?`<span class="stars">${'★'.repeat(e.tier)}${'☆'.repeat(3-e.tier)}</span><span class="num muted" style="font-size:17px">BEST ${e.best}/6</span>`:G.world?'<span class="chip amber">PREVIEW</span>':'<span class="chip">LOCKED</span>'}</span>`);
    b.onclick=()=>{sfx.tap();if(open)startGym(G.id);else if(G.world){const m=modal(`<p class="eyebrow">LOCKED GAME</p><h2>${G.name}</h2><p>${G.intro}</p><p class="muted">${G.how}. You can play a preview now; it counts toward your Listening mastery.</p><button class="btn block gp-go">PLAY PREVIEW</button><button class="btn ghost block gp-x">NOT NOW</button>`,{dismiss:true});$('.gp-go',m).onclick=()=>{m.close();startGym(G.id,true)};$('.gp-x',m).onclick=()=>m.close()}else toast('LOCKED · '+G.how.toUpperCase())};gl.append(b)});
  const rb=$('[data-a=recall]',scr);if(rb)rb.onclick=()=>{sfx.tap();startRecall()};$$('[data-pq]',scr).forEach(b=>b.onclick=()=>{sfx.tap();startPQ(+b.dataset.pq)})};

