let pathTab='rank';
function triBars(id){const s=S.skills[id]||{u:0,l:0,p:0};return`<div class="tri">${[['u','Understand','var(--violet)'],['l','Listening','var(--neon)'],['p','Practical','var(--amber)']].map(([k,n,c])=>`<div>${n} ${Math.round(s[k])}%<span class="bar"><i style="width:${s[k]}%;--c:${c}"></i></span></div>`).join('')}</div>`}
RENDER.path=scr=>{const lp=lvProg();const rk=rankFor(lp.n),rn=rankNext(lp.n);const tabs=[['rank','RANK'],['skills','SKILLS'],['abilities','ABILITIES'],['tools','TOOLS'],['monsters','MONSTERS'],['style','STYLE']];
  scr.innerHTML=topbar('PRODUCER PATH')+`<div class="stack"><div class="win raised stack"><div class="row sp"><span class="eyebrow">PRODUCER LV ${lp.n}</span><span class="chip violet">${learnedSkills().length}/43 SKILLS</span></div><h3>“${rk[1]}”</h3>${rn?`<p class="muted" style="font-size:14.5px">Next milestone at LV ${rn[0]}: “${rn[1]}”</p>`:''}</div>
   <div class="subtabs">${tabs.map(([k,n])=>`<button data-t="${k}" class="${pathTab===k?'on':''}">${n}</button>`).join('')}</div><div class="stack pc"></div></div>`;hydrateIcons(scr);
  $$('[data-t]',scr).forEach(b=>b.onclick=()=>{pathTab=b.dataset.t;sfx.tap();RENDER.path(scr)});const c=$('.pc',scr);
  if(pathTab==='rank'){c.innerHTML=`<p class="muted">Your levels track who you are becoming as a producer. Each milestone is a real-world ability.</p><div class="ladder">${RANKS.map(r=>{const cls=lp.n>=r[0]&&(rankNext(lp.n)||[99])[0]>r[0]&&rk===r?'cur':lp.n>=r[0]?'done':'fut';return`<div class="rung ${cls}"><span class="num">LV ${r[0]}</span><span>“${r[1]}”<small>${r[2]}</small></span></div>`}).join('')}</div>
    <div class="win stack"><p class="eyebrow">THE FINAL TRACK</p><p style="font-size:15px">At the end of the campaign you get a blank project. You choose the tempo, drums, bass, melody, arrangement, sound design, EQ, compression, reverb, automation and mastering. PIP can hint, never solve. Finish it and you are <b style="color:var(--amber)">PRODUCER CERTIFIED</b>.</p>${S.cert?`<span class="chip neon">CERTIFIED · SCORE ${S.cert.score}</span><button class="btn block" data-a="fin">OPEN THE DAW</button>`:S.done.includes('master')?'<button class="btn block" data-a="fin">OPEN THE FINAL TRACK</button>':'<span class="chip">LOCKED · DEFEAT THE MASTER</span>'}</div>`;const fb=$('[data-a=fin]',c);if(fb)fb.onclick=()=>go('final')}
  if(pathTab==='skills'){TIERS.forEach(T=>{const list=SKILLS.filter(s=>s[2]===T.id);const sec=h('div','stack');sec.innerHTML=`<div class="tierhead"><h3>${T.name}</h3><span class="num" style="font-size:22px;color:var(--amber)">${Math.round(tierMastery(T.id))}%</span></div><p class="muted" style="font-size:14px">${T.sub}</p><div class="skills"></div>`;
    const sl=$('.skills',sec);list.forEach(s=>{const id=s[0],vis=skillVisible(id),st=S.skills[id];const b=h('button','skill'+(vis?'':' unk'));
      b.innerHTML=vis?`<span class="n">${s[1]}${st&&st.learned?' '+memoHtml(st.box):''}</span><span class="pct">${ovr(id)}%</span>${triBars(id)}`:`<span class="n">???</span><span class="muted" style="font-size:13px">${WNAME[s[3]]}</span>`;
      b.onclick=()=>{sfx.tap();if(vis)skillInfo(id);else toast('UNKNOWN SKILL · TAUGHT IN '+WNAME[s[3]].toUpperCase())};sl.append(b)});c.append(sec)})}
  if(pathTab==='abilities'){c.innerHTML='<p class="muted">Abilities are permanent. You earn each one by understanding something real.</p>';ABILITIES.forEach(a=>{const hv=hasAb(a.id);const d=h('div','abil'+(hv?' have':''));d.append(hv?icon('bolt','#a98bff',4):sprite(ICONS.bolt,DIM_PAL,4));d.insertAdjacentHTML('beforeend',`<div class="stack" style="gap:3px"><span class="t">${hv||a.from?(hv?a.name:'???'):'???'}</span><p>${hv?a.desc:a.from?`Learn “${a.from}” to unlock.`:`Waits in ${WNAME[a.world]}.`}</p></div>`);c.append(d)})}
  if(pathTab==='tools'){c.innerHTML=`<p class="muted">Every production tool is a weapon. You earn each one by learning it. ${S.tools.length} of ${TOOLS.length} unlocked.</p><div class="tools"></div>`;const tg=$('.tools',c);
    TOOLS.forEach(t=>{const hv=has(t.id);const ids=TOOL_SKILLS[t.id]||[];const ms=Math.round(ids.reduce((a,k)=>a+ovr(k),0)/Math.max(1,ids.length));const b=h('button','tool '+(hv?'have':'locked'));b.append(icon(t.id,t.col,4,!hv));
      b.insertAdjacentHTML('beforeend',`<span class="n">${hv?t.name:'???'}</span><span class="w">${hv?t.weapon:'Unknown tool'}</span><span class="r">LV ${t.lv} · ${t.world.toUpperCase()}</span>${hv?`<div class="bar"><i style="width:${ms}%"></i></div><span class="r">MASTERY ${ms}% · ${S.missions[t.id]||0} MISSIONS${ms>=90?' · MASTERED':''}</span>`:'<span class="r">LOCKED</span>'}`);b.onclick=()=>{sfx.tap();toolInfo(t,ms)};tg.append(b)})}
  if(pathTab==='monsters'){const known=Object.keys(MONS).filter(k=>S.seen.includes(k)).length;c.innerHTML=`<p class="muted">${known} of ${Object.keys(MONS).length} discovered. Every monster is a musical problem in disguise.</p><div class="beasts"></div>`;const bg=$('.beasts',c);
    Object.keys(MONS).forEach(k=>{const M=MONS[k];const seen=S.seen.includes(k),def=S.defeated.includes(k);const d=h('button','beast'+(def?' def':'')+(seen?'':' unk'));d.append(seen?monEl(k,3):sprite(SLIME,SIL_PAL,3));d.insertAdjacentHTML('beforeend',`<span>${seen?M.name.toUpperCase():'???'}</span><span style="color:${def?'var(--neon)':'var(--dim)'}">${def?'DEFEATED':seen?'SEEN':WNAME[M.world].toUpperCase()}</span>`);
      d.onclick=()=>{if(!seen){toast('UNKNOWN MONSTER · '+WNAME[M.world].toUpperCase());return}const m=modal(`<div class="mi"></div><h2>${M.name}</h2><p><b style="color:var(--magenta)">Musical problem:</b> ${M.problem}</p><p class="muted">Beaten with: ${M.weak}</p><button class="btn block mi-x">CLOSE</button>`,{dismiss:true});$('.mi',m).append(monEl(k,6));$('.mi-x',m).onclick=()=>m.close()};bg.append(d)})}
  if(pathTab==='style'){const slots=[['hoodie','HOODIE'],['phones','HEADPHONES'],['hair','HAIR'],['comp','COMPANION']];c.innerHTML=`<div class="win dressing"></div><p class="muted" style="font-size:14px">Cosmetics are just for style. They never change combat or scores. You have ${S.coins} coins.</p>${slots.map(([s,n])=>`<div class="stack" style="gap:8px"><p class="eyebrow">${n}</p><div class="swatches">${COS.filter(x=>x.slot===s).map(x=>{const own=S.owned.includes(x.id);return`<button class="sw ${S.eq[s]===x.id?'on':''} ${own?'':'lock'}" data-c="${x.id}"><i style="background:${x.col}"></i>${x.name}${own?'':x.price?` · <span style="color:var(--amber)">${x.price}c</span>`:' · LOCKED'}</button>`}).join('')}</div></div>`).join('')}`;
    const dr=$('.dressing',c);dr.append(heroEl(6,'bob'));const cp=companionEl(4);if(cp)dr.append(cp);
    $$('[data-c]',c).forEach(b=>b.onclick=()=>{const x=cos(b.dataset.c);if(!S.owned.includes(x.id)){if(x.price){if(b.dataset.arm){if(S.coins>=x.price){S.coins-=x.price;S.owned.push(x.id);S.eq[x.slot]=x.id;save();sfx.coin();RENDER.path(scr)}else{toast('NOT ENOUGH COINS · QUESTS AND BATTLES EARN MORE');sfx.bad()}}else{b.dataset.arm=1;b.innerHTML=`<i style="background:${x.col}"></i>TAP TO BUY · ${x.price}c`}}else toast('LOCKED · '+x.how.toUpperCase());return}S.eq[x.slot]=x.id;save();sfx.tap();RENDER.path(scr)})}};
function skillInfo(id){const s=S.skills[id]||{u:0,l:0,p:0};const K=SK[id];const due=s.learned&&s.due?dayDiff(todayStr(),s.due):null;
  const m=modal(`<p class="eyebrow">${TIERS.find(t=>t.id===K.t).name.toUpperCase()} · ${WNAME[K.w].toUpperCase()}</p><h2>${K.n}</h2><p>${K.d}</p><p class="num" style="font-size:44px;line-height:.9;color:var(--amber)">${ovr(id)}%</p>
   <div class="mbars">${[['u','Understanding','var(--violet)','Lessons and concept checks'],['l','Listening','var(--neon)','Ear Gym and ear tests'],['p','Practical','var(--amber)','Building, fixing and battles']].map(([k,n,c,why])=>`<span>${n}<br><small class="muted">${why}</small></span><span class="bar"><i style="width:${s[k]}%;--c:${c}"></i></span><span class="num">${Math.round(s[k])}</span>`).join('')}</div>
   ${s.learned?`<p class="muted" style="font-size:14.5px">Memory ${memoHtml(s.box)} · ${due>0?`next recall in ${due} day${due===1?'':'s'}`:'recall due now'}</p>`:'<p class="muted" style="font-size:14.5px">Not learned yet. Its lesson schedules the first recall.</p>'}
   ${SKILL_Q[id]&&(s.learned||s.u+s.l+s.p>0)?'<button class="btn block si-p">PRACTICE NOW · 3 QUESTIONS</button>':''}<button class="btn ghost block si-x">CLOSE</button>`,{dismiss:true});
  const p=$('.si-p',m);if(p)p.onclick=()=>{m.close();startPractice(id)};$('.si-x',m).onclick=()=>m.close()}
function toolInfo(t,ms){const hv=has(t.id);const m=modal(`<div class="ti-ic"></div><p class="eyebrow">${hv?'WEAPON FORM · '+t.weapon.toUpperCase():'LOCKED · LV '+t.lv+' · '+t.world.toUpperCase()}</p><h2>${hv?t.name:'???'}</h2><p>${hv?t.desc:'You will discover this tool when you understand what it does.'}</p>${hv?`<div class="win raised" style="text-align:left;width:100%"><p class="eyebrow" style="margin-bottom:6px">IN A REAL DAW</p><p style="font-size:15px">${t.daw}</p></div><p class="muted">Mastery ${ms}% · ${S.missions[t.id]||0} missions completed</p>`:''}<button class="btn block ti-x">${hv&&t.id!=='volume'?'USE IN STUDIO':'CLOSE'}</button>`,{dismiss:true});
  $('.ti-ic',m).append(icon(t.id,t.col,8,!hv));$('.ti-x',m).onclick=()=>{m.close();if(hv&&t.id!=='volume')go('studio')}}

/* ================= daily quests ================= */
RENDER.quests=scr=>{const d=new Date(),mid=new Date(d);mid.setHours(24,0,0,0);const ms=mid-d;const hh=Math.floor(ms/3.6e6),mm=Math.floor(ms%3.6e6/6e4);
  scr.innerHTML=topbar('DAILY QUESTS','home')+`<p class="muted">New quests in <span class="num" style="font-size:19px;color:var(--ink)">${hh}h ${mm}m</span>. Quests reward XP, coins, drum kits and cosmetics.</p><div class="stack ql" style="margin-top:12px"></div>`;wireBack(scr);
  const ql=$('.ql',scr);QUESTS.forEach(q=>{const pr=S.quests.prog[q.id]||0,claimed=S.quests.claimed.includes(q.id),lock=q.needs==='drums'?!has('drums'):q.needs==='ear'?!GAMES.some(g=>g.unlocked()):false,done=pr>=q.goal;
    const c=h('div','win quest'+(claimed?' claimed':''));c.innerHTML=`<canvas class="px" data-ic="${q.icon}" data-sc="4"${lock?' data-dim="1"':''}></canvas><div class="grow stack" style="gap:4px"><span class="t">${q.title}</span><span class="d">${lock?(q.needs==='ear'?'Unlocks after “What is Sound?”':'Unlocks with the Drum Machine'):q.desc}</span><div class="bar" style="height:9px"><i style="width:${pr/q.goal*100}%;--c:var(--neon)"></i></div><span class="rw">+${q.xp} XP · +${q.coins} COINS${q.reward?' · '+cos(q.reward).name.toUpperCase():''}</span></div>${claimed?'<span class="chip neon">DONE</span>':done?'<button class="btn sm neon">CLAIM</button>':`<span class="num muted" style="font-size:20px">${pr}/${q.goal}</span>`}`;
    const b=$('button',c);if(b)b.onclick=async()=>{b.disabled=true;S.quests.claimed.push(q.id);save();await reward({eyebrow:'QUEST REWARD',title:q.title.toUpperCase(),xp:q.xp,coins:q.coins,cosmetics:q.reward?[q.reward]:[]});RENDER.quests(scr)};ql.append(c)});hydrateIcons(scr)};

/* ================= AI coach ================= */
let samplePromise=null;
function getSample(){if(!samplePromise)samplePromise=(window.claude&&window.claude.use?Promise.resolve(window.claude.use('sample')):Promise.resolve(null)).catch(()=>null);return samplePromise}
const CANNED={
'Why does my bass sound muddy?':'Muddy bass usually means too many sounds are fighting in the low frequencies. Often it is the kick and the bass hitting at the same moment with the same weight.\n\nQuick fixes: let the kick and bass take turns (put bass notes between kicks), or turn one of them down a little.\n\nTry it: in your studio, move a bass note off step 1 so it lands just after the kick. In the EQ Desert you will learn to carve the lows with an EQ.',
'How do I make my kick punchier?':'Punch is mostly about contrast. A kick feels punchy when it has room around it.\n\nGive it space: keep other drums off the exact same step, and turn the hats and bass down a touch so the kick stands out.\n\nTry it: in your studio set the kick fader around 90 and the hats around 45. A compressor with a slower attack adds even more snap.',
'What does attack mean on a compressor?':'A compressor turns loud moments down. Attack is how fast it reacts.\n\nFast attack grabs the very start of a sound and flattens it. Slow attack lets the first hit through before clamping down, which makes drums sound punchier.\n\nTry “Taming Peaks” in Compression Volcano: you can hear this happen live.',
'Why does my mix sound quiet?':'Usually one of two things: everything is turned down, or one sound is so loud it forces everything else down with it.\n\nBalance first. Find your loudest element (often the kick) and make everything else sit around it. Loudness comes at the very end, with a Limiter in the Mastering Sky.\n\nTry it: bring every studio fader to about 70, then nudge each one until nothing hides.',
'How do I make a synth sound darker?':'Dark means less high frequency. The main tool is a low-pass filter: it lets the lows through and cuts the highs.\n\nTurn the filter cutoff down and the synth gets warmer and darker. A softer waveform (sine or triangle instead of saw) helps too.\n\nYou will learn this hands-on in the Synth Caves.',
'What is BPM?':'BPM means beats per minute: how many beats happen in one minute. It sets the speed of a song.\n\n60 BPM is one beat per second, 120 BPM is two. Lo-fi hip-hop often sits around 70 to 90, house around 120 to 128, drum & bass around 170.\n\nTry it: in your studio, press play and tap + or − on the tempo. Same pattern, different mood.',
'What does quantize do?':'Quantize snaps notes onto a grid so they land exactly in time.\n\nWhen you play notes by hand, some are a little early or late. Quantize moves each one to the nearest grid line. Pick the grid that matches your rhythm: 1/8 for eighth notes, 1/16 for faster sixteenths.\n\nIn a real DAW, select the notes and use the Quantize command.',
'Why are there 16 steps?':'One bar of 4/4 has 4 beats. A step sequencer splits each beat into 4 smaller steps, so 4 × 4 = 16 steps.\n\nSteps 1, 5, 9 and 13 are the beats. The steps in between are where hi-hats, extra kicks and syncopation live.\n\nTry it: put a hi-hat on every odd step, then add one on step 16 and hear the little push into the next bar.',
'How do I make my beat groove more?':'Groove comes from contrast and small surprises.\n\n- Add a hit on an in-between step (like step 11 or 16) for syncopation.\n- Keep the hi-hats quieter than the kick and snare.\n- Leave some gaps. Silence makes the hits feel bigger.\n\nTry it: in your studio, move one kick from step 9 to step 11 and listen to the bounce.',
'What is the difference between kick and snare?':'The kick is the low thump you feel in your chest. It usually lands on beats 1 and 3 and anchors the groove.\n\nThe snare is the bright crack. On beats 2 and 4 it becomes the backbeat, the part people clap to.\n\nTry it: put the kick on steps 1 and 9 and the snare on steps 5 and 13. That is the backbeat.'};
function openCoach(){const sh=h('div','sheet');const turns=[];let ctl=null,busy=false;
  sh.innerHTML=`<div class="sheet-in"><div class="sheet-h"><span class="pipbox"></span><div class="grow"><h3>PIP</h3><p class="muted" style="font-size:14px">Producer mentor · explains at your level (LV ${level()})</p></div><button class="iconbtn" data-a="close" aria-label="Close">✕</button></div><div class="msgs"></div><div class="chips">${Object.keys(CANNED).map(q=>`<button>${q}</button>`).join('')}</div><form class="composer"><input id="coach-in" placeholder="Ask about beats, mixing, sound…" autocomplete="off" aria-label="Ask PIP a question"><button class="btn sm" type="submit">ASK</button></form></div>`;
  app.append(sh);$('.pipbox',sh).append(pipEl(3,'float'));const msgs=$('.msgs',sh);
  const add=(txt,who)=>{const m=h('div','msg '+who);m.textContent=txt;msgs.append(m);msgs.scrollTop=msgs.scrollHeight;return m};
  add('Hey producer! I’m PIP. Ask me anything about making music. I’ll keep it simple and tell you where in the adventure you’ll master it.','pip');
  getSample().then(s=>{if(s||!sh.isConnected)return;$('.composer',sh).hidden=true;$('.chips',sh).classList.add('wrap');add('Offline coach: tap a question below.','note')});
  const close=()=>{if(ctl)ctl.abort();sh.remove()};$('[data-a=close]',sh).onclick=close;sh.addEventListener('click',e=>{if(e.target===sh)close()});
  const RULES=()=>{const wk=weakTags().slice(0,2).map(t=>TAGNAME[t]||t);const due=dueSkills().map(id=>SK[id].n);
    return`You are PIP, a small amber speaker-robot who mentors players in BEAT QUEST, a pixel-art RPG that teaches music production. Talk like a friendly, encouraging producer. The player is Producer Level ${level()}. Skills they have learned: ${learnedSkills().map(id=>SK[id].n).join(', ')||'none yet'}. Unlocked tools: ${S.tools.join(', ')}. ${wk.length?'They currently struggle with: '+wk.join(' and ')+'. If relevant, gently help with that.':''} ${due.length?'Skills due for review: '+due.join(', ')+'.':''} Rules: plain language for a beginner; define any technical word the first time you use it; at most about 110 words; give one concrete example; end with one small thing to try (in the game's studio drum machine if it fits, otherwise in any DAW). Never just hand over a full solution to a challenge in the game: give a hint that makes them listen. Plain text only: no markdown headings, no asterisks, at most 3 short bullet lines. If the topic is beyond their level, give the simple version and name the world that teaches it: Synth Caves (MIDI, notes, scales, chords, synths, ADSR, filters, LFO), EQ Desert (EQ, frequencies, masking), Compression Volcano (compression, distortion), Reverb Swamp (reverb, delay), Mixing Castle (volume, gain staging, panning, stereo, automation), Mastering Sky (limiting, LUFS, headroom, export).`};
  const ask=async q=>{q=q.trim();if(!q||busy)return;busy=true;add(q,'me');$('#coach-in',sh).value='';const bub=add('Thinking…','pip');const sample=await getSample();
    const fallback=()=>{const k=Object.keys(CANNED).find(x=>x.toLowerCase()===q.toLowerCase());bub.textContent=k?CANNED[k]:'Live answers aren’t available in this view, so I can only answer the questions below. Tap one of them.'};
    if(!sample){fallback();busy=false;return}
    turns.push({role:'user',content:q});ctl=new AbortController();
    try{const {text}=await sample([{role:'user',content:RULES()}].concat(turns.slice(-8)),{cache:false,modelTier:'quick',signal:ctl.signal,onText:({text})=>{bub.textContent=text;msgs.scrollTop=msgs.scrollHeight}});turns.push({role:'assistant',content:text})}
    catch(e){turns.pop();const code=e&&e.code;if(code==='cancelled'){}else if(e&&e.text)bub.textContent=e.text;else if(['not_granted','sampling_disabled','not_declared','capability_disabled','capability_removed'].includes(code))fallback();else if(code==='rate_limited')bub.textContent='I need a short break. Ask me again in a minute.';else if(code==='refused')bub.textContent='I can’t help with that one. Ask me something about making music.';else bub.textContent='My signal dropped. Ask again in a moment.'}
    finally{busy=false}};
  $$('.chips button',sh).forEach(b=>b.onclick=()=>ask(b.textContent));$('.composer',sh).onsubmit=e=>{e.preventDefault();ask($('#coach-in',sh).value)}}

/* ================= platform hooks: Android back button, app pause ================= */
window.bqBack=()=>{const sh=$('.sheet');if(sh){const c=$('[data-a=close]',sh);if(c)c.click();else sh.remove();return'ok'}
  const mods=$$('.modal-back');if(mods.length){const m=mods[mods.length-1];const b=$('.rw-go,.ul-later,.ab-ok,.sb-again,.kit-done,.st-cl,.wi-ok,.gp-x,.si-x,.mi-x,.ti-x,.rv-ok,.tr-ok,.fx-close,.x-ok',m);if(b)b.click();else m.remove();return'ok'}
  if(cur==='final'&&window.bqFinalBack&&bqFinalBack())return'ok';
  const up={lesson:'region',battle:'region',trial:'region',play:playBack,region:'map',studio:$('#s-studio [data-back]')?'region':'home',map:'home',train:'home',path:'home',quests:'home',victory:'home',final:S.cert?'home':'region',cert:'home'}[cur];
  if(up){sfx.tap();S.daily.active=null;save();go(up);return'ok'}return'exit'};
window.bqPause=()=>{if(CLOUD.on)cloudPush();seq.stop();stopGroup();stopMusic();if(A.ctx&&A.ctx.state==='running')A.ctx.suspend()};
window.bqResume=()=>{if(!A.ctx)return;const p=A.ctx.resume();if(p&&p.catch)p.catch(()=>{});if(['home','map','region','train','path','quests'].includes(cur))startMusic()};
document.addEventListener('visibilitychange',()=>{if(document.hidden)bqPause();else bqResume()});

